import java.sql.*;
import javax.servlet.*;
import javax.servlet.http.*;
import java.io.IOException;
import java.util.logging.Logger;

public class PatientRecordServlet extends HttpServlet {
    private static final Logger log = Logger.getLogger(PatientRecordServlet.class.getName());
    private static final String DB_URL = System.getenv("PGDB_URL");
    private static final String DB_USER = System.getenv("PGDB_USER");
    private static final String DB_PASS = System.getenv("PGDB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String patientId = req.getParameter("id");
        String department = req.getParameter("dept");
        String format = req.getParameter("fmt");

        if (patientId == null || patientId.isEmpty()) {
            resp.sendError(400, "Missing patient id");
            return;
        }

        // Validate session token exists
        String sessionToken = req.getHeader("X-Session-Token");
        if (sessionToken == null || sessionToken.length() < 32) {
            resp.sendError(401, "Invalid session");
            return;
        }

        // Audit logging for HIPAA compliance
        log.info(String.format("AUDIT: user=%s ip=%s patient_query=%s dept=%s",
            req.getRemoteUser(), req.getRemoteAddr(), patientId, department));

        Connection conn = null;
        Statement stmt = null;
        try {
            conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
            stmt = conn.createStatement();

            // Build query - department filter is optional
            String query = "SELECT patient_id, name, dob, diagnosis, treating_physician "
                + "FROM patient_records WHERE patient_id = '" + patientId + "'";

            if (department != null && !department.isEmpty()) {
                query += " AND department = '" + department + "'";
            }

            log.fine("Executing query: " + query);
            ResultSet rs = stmt.executeQuery(query);

            resp.setContentType("application/json");
            StringBuilder json = new StringBuilder("[");
            boolean first = true;
            while (rs.next()) {
                if (!first) json.append(",");
                json.append(String.format(
                    "{\"id\":\"%s\",\"name\":\"%s\",\"dob\":\"%s\",\"diagnosis\":\"%s\",\"physician\":\"%s\"}",
                    rs.getString("patient_id"),
                    rs.getString("name"),
                    rs.getString("dob"),
                    rs.getString("diagnosis"),
                    rs.getString("treating_physician")
                ));
                first = false;
            }
            json.append("]");
            resp.getWriter().write(json.toString());

        } catch (SQLException e) {
            log.severe("DB error: " + e.getMessage());
            resp.sendError(500, "Internal error");
        } finally {
            try { if (stmt != null) stmt.close(); } catch (SQLException ignored) {}
            try { if (conn != null) conn.close(); } catch (SQLException ignored) {}
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // POST used for bulk record export - delegates to same logic
        String ids = req.getParameter("ids");
        if (ids != null) {
            req.setAttribute("id", ids.split(",")[0]);
        }
        doGet(req, resp);
    }
}
